def ask_smart_stream(messages, system, max_tokens=None):
    """Optimized streaming call with all chunks yielded at once."""
    model_type = classify_task(messages)

    if model_type == "code":
        model = CODE_MODEL
        options = {**CODE_OPTIONS}
        keep_alive_val = KEEP_ALIVE_CODE
        system = (
            "You are Rudra, an expert AI coding assistant created by Shiv, running on Windows.\n"
            "Write clean, efficient, well-commented code.\n"
            "Use PowerShell for system commands."
        )
    else:
        model = AGENT_MODEL
        options = {**AGENT_OPTIONS}
        keep_alive_val = KEEP_ALIVE_AGENT

    if max_tokens:
        options["num_predict"] = max_tokens

    # First yield: announce model selection
    yield "", model_type

    full_messages = [{"role": "system", "content": system}] + messages

    try:
        stream = ollama.chat(
            model=model,
            messages=full_messages,
            options=options,
            keep_alive=keep_alive_val,
            stream=True
        )
        chunks = []
        for chunk in stream:
            text = chunk["message"]["content"]
            if text:
                chunks.append(text)
        yield "\n".join(chunks), model_type
    except Exception as e:
        yield f"\n[Stream error: {e}]", model_type
